## Examples

### Browser

```typescript
import { PolyvocoderClient } from "@superinstance/polyvocoder";

const client = new PolyvocoderClient("https://polyvocoder.example.com");
const result = await client.runPipeline({
  text: "The canon gate made itself heard.",
});
document.body.innerText = result.decodedSamples[0].text;
```

### Node

```typescript
import { PolyvocoderClient } from "@superinstance/polyvocoder";

const client = new PolyvocoderClient();
const result = await client.runPipeline({ text: "..." });
// process result.features, result.decodedSamples
```

### Cloudflare Worker

```typescript
import { PolyvocoderClient } from "@superinstance/polyvocoder";

export default {
  async fetch(request: Request): Promise<Response> {
    const { text } = await request.json();
    const client = new PolyvocoderClient(env.POLYVOCODER_URL);
    const result = await client.runPipeline({ text, nSamples: 1 });
    return new Response(JSON.stringify(result), {
      headers: { "Content-Type": "application/json" },
    });
  },
};
```

### React

```tsx
import { useState, useEffect } from "react";
import { PolyvocoderClient } from "@superinstance/polyvocoder";

function CanonRenderer({ lore }: { lore: string }) {
  const [result, setResult] = useState<any>(null);

  useEffect(() => {
    const client = new PolyvocoderClient();
    client.runPipeline({ text: lore, nSamples: 1 }).then(setResult);
  }, [lore]);

  if (!result) return <div>Loading...</div>;

  return (
    <div>
      <pre>{result.features}</pre>
      <pre>{result.decodedSamples[0].text}</pre>
      <pre>{result.decodedSamples[0].image}</pre>
    </div>
  );
}
```

## Fleet Canary

This binding pins to the Quilt fleet canary:
**`fnv1a-64('café Δ 日本語') = 0x024a555471370b18d`**

All polyformalism ports must reproduce this byte-exact. The TypeScript binding
inherits this from the Python implementation. See
[`docs/FLEET_CANARY.md`](../../polyvocoder/docs/FLEET_CANARY.md) in the main repo.

## Building

```bash
npm install
npm run build
```

Output is in `dist/`. Import via:

```typescript
import { PolyvocoderClient } from "@superinstance/polyvocoder";
```

